def prep(sql, save, out):
    n = sql("select mgrno, mgrname, country, rdate1, rdate2 from tfn.s34names")
    save("eq_s34names", n)
    f = sql("select h.crsp_fundno, h.crsp_portno, h.crsp_cl_grp, h.fund_name, h.mgmt_name, h.adv_name, h.mgr_name, "
            "h.mgr_dt, h.first_offer_dt, h.end_dt, h.index_fund_flag, h.et_flag, h.dead_flag from crsp.fund_hdr h")
    t = sql("select crsp_fundno, count(*) as months, avg(mtna) as tna, min(caldt) as d0, max(caldt) as d1 "
            "from crsp.monthly_tna_ret_nav where caldt >= '2011-01-01' and mret is not null group by 1")
    s = sql("select distinct on (crsp_fundno) crsp_fundno, crsp_obj_cd from crsp.fund_style order by crsp_fundno, begdt desc")
    f = f.merge(t, on="crsp_fundno", how="left").merge(s, on="crsp_fundno", how="left")
    save("eq_fundhdr", f)
    out("prep: s34names rows", len(n), "| distinct mgrno", n.mgrno.nunique(), "| fund header rows", len(f),
        "| funds with months since 2011", int(f.months.notna().sum()))


def run(load, out, pd, part, parts):
    names = load("eq_s34names")
    names["nm"] = names.mgrname.fillna("").astype(str)
    q = load("eq_mgrq")
    q["rdate"] = pd.to_datetime(q.rdate)
    g = q.groupby("mgrno").agg(nq=("rdate", "count"), pos=("npos", "median"), val=("val_m", "median"),
                               r0=("rdate", "min"), r1=("rdate", "max"))
    f = load("eq_fundhdr")
    for c in ("fund_name", "mgmt_name", "adv_name", "mgr_name"):
        f[c] = f[c].fillna("").astype(str)
    for c in ("d0", "d1", "mgr_dt"):
        f[c] = f[c].astype(object).where(f[c].notna(), "").astype(str).str[:10].replace({"nan": "", "None": "", "NaT": ""})
    for c in ("index_fund_flag", "et_flag", "crsp_obj_cd"):
        f[c] = f[c].fillna("").astype(str)
    f["tna"] = pd.to_numeric(f.tna, errors="coerce")
    f["months"] = pd.to_numeric(f.months, errors="coerce")
    f["txt"] = f.fund_name + " | " + f.mgmt_name + " | " + f.adv_name
    f["grp"] = f.crsp_cl_grp.fillna(-f.crsp_portno.fillna(f.crsp_fundno))
    mine = [p for i, p in enumerate(INV) if i % parts == part]
    for p in mine:
        out("## %s %s | %s" % (p["id"], p["name"], "; ".join(p["firms"])[:90]))
        hit = pd.Series(False, index=names.index)
        fh = pd.Series(False, index=f.index)
        for x in p["patterns"]:
            try:
                hit |= names.nm.str.contains(x, case=False, regex=True)
                fh |= f.txt.str.contains(x, case=False, regex=True)
            except re.error:
                out("   bad pattern", x)
        sur = p.get("surname") or ""
        if sur:
            m = f.mgr_name.str.contains(r"\b%s\b" % re.escape(sur), case=False, regex=True)
            if sur in COMMON or len(sur) < 6:
                m &= f.mgr_name.str.contains(r"\b%s" % re.escape(p["first"][:4]), case=False, regex=True)
            fh |= m
        c = names[hit].groupby("mgrno").agg(nm=("nm", lambda s: " / ".join(sorted(set(s))[:3])),
                                            country=("country", "first"))
        c = c.join(g, how="left").sort_values(["nq", "val"], ascending=False)
        out("   13F candidates: %d" % len(c))
        for mg, r in c.head(6).iterrows():
            if pd.isna(r.nq):
                out("   F %d | %s | %s | no holdings filed for 2010-06 or later" % (mg, r.nm[:70], str(r.country)[:12]))
            else:
                out("   F %d | %s | %s | quarters %d (%s to %s) | positions median %d | value median $%dM"
                    % (mg, r.nm[:70], str(r.country)[:12], r.nq, str(r.r0)[:7], str(r.r1)[:7], r.pos, r.val))
        d = f[fh]
        if len(d):
            k = d.sort_values("tna", ascending=False).groupby("grp").agg(
                fund=("fund_name", "first"), mgr=("mgr_name", "first"), mgr_dt=("mgr_dt", "first"),
                mgmt=("mgmt_name", "first"), obj=("crsp_obj_cd", "first"), months=("months", "max"),
                tna=("tna", "sum"), cls=("crsp_fundno", "count"), fno=("crsp_fundno", "first"),
                idx=("index_fund_flag", "first"), etf=("et_flag", "first"), d0=("d0", lambda x: min([v for v in x if v] or [""])), d1=("d1", "max"))
            k = k.sort_values(["months", "tna"], ascending=False)
            out("   fund candidates: %d" % len(k))
            for _, r in k.head(7).iterrows():
                out("   M fundno %d (%d classes) | %s | mgr %s since %s | %s | obj %s | months since 2011: %s (%s to %s) | mean assets $%sM%s%s"
                    % (r.fno, r.cls, r.fund[:60], r.mgr[:28], str(r.mgr_dt)[:7], r.mgmt[:30], r.obj,
                       "none" if pd.isna(r.months) else int(r.months), str(r.d0)[:7], str(r.d1)[:7],
                       "?" if pd.isna(r.tna) else int(r.tna), " | index" if r.idx else "",
                       " | ETF" if r.etf else ""))
        else:
            out("   fund candidates: 0")
